// Edit this list to add or remove lender websites. Failures on one site never stop the others.
const sources = [
  { source: 'mock-bank-a', url: 'http://mock-sites/bank-a.html' },   // article cards with data-* attributes
  { source: 'mock-bank-b', url: 'http://mock-sites/bank-b.html' },   // table rows, same data-* convention
  { source: 'mock-bank-c', url: 'http://mock-sites/bank-c.html' },   // unstructured prose -> LLM extraction
  // Optional live site (may block bots; the pipeline tolerates failures):
  // { source: 'bankbazaar', url: 'https://www.bankbazaar.com/personal-loan.html' },
];
return sources.map(s => ({ json: s }));

// Layer 1 (free, fast, deterministic): read data-* attributes straight from the HTML.
// Layer 2 (only if layer 1 finds nothing): pass cleaned page text to the LLM.
const sources = $('Source List').all();
const out = [];
$input.all().forEach((item, i) => {
  const src = sources[i].json;
  const html = typeof item.json.data === 'string' ? item.json.data : '';
  if (!html) {
    out.push({ json: { source: src.source, url: src.url, products: [], needs_llm: false,
                       error: (item.json.error && item.json.error.message) || 'empty response' } });
    return;
  }
  const products = [];
  const tags = html.match(/<[^>]*\sdata-product-name="[^"]*"[^>]*>/gi) || [];
  for (const tag of tags) {
    const a = {};
    for (const m of tag.matchAll(/data-([a-z-]+)="([^"]*)"/gi)) a[m[1].toLowerCase()] = m[2];
    products.push({
      product_name: a['product-name'], provider: a['provider'] || src.source,
      interest_rate: a['interest-rate'], min_monthly_income: a['min-income'],
      min_credit_score: a['min-score'], max_credit_score: a['max-score'],
      min_age: a['min-age'], max_age: a['max-age'],
      allowed_employment: a['employment'], eligibility_text: a['notes'] || '',
    });
  }
  const text = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 12000);
  out.push({ json: { source: src.source, url: src.url, products,
                     needs_llm: products.length === 0 && text.length > 200, page_text: text } });
});
return out;

// Merge the LLM's JSON answer back with its source. If the LLM is unavailable the source simply yields 0 products.
const meta = $('Needs LLM?').all(0);
return $input.all().map((item, i) => {
  const m = meta[i].json;
  let products = [], error = null;
  try {
    const txt = item.json.candidates[0].content.parts[0].text;
    const parsed = JSON.parse(txt);
    products = Array.isArray(parsed) ? parsed : (parsed.products || []);
  } catch (e) {
    error = 'LLM extraction unavailable: ' + ((item.json.error && item.json.error.message) || e.message);
  }
  return { json: { source: m.source, url: m.url, products, error, via: 'llm' } };
});

// Validate + normalise every product so garbage (from HTML or LLM) never reaches the database.
const num = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const canon = s => String(s).toLowerCase().replace(/[^a-z]+/g, '-').replace(/^-|-$/g, '');
const SYN = { 'selfemployed': 'self-employed', 'self': 'self-employed', 'salary': 'salaried',
              'employed': 'salaried', 'business': 'self-employed', 'business-owner': 'self-employed' };
const emp = v => {
  const list = Array.isArray(v) ? v : String(v || '').split(',');
  return list.map(x => canon(x)).filter(Boolean).map(x => SYN[x] || x).join(',');
};
return $input.all().map(item => {
  const j = item.json;
  const good = [];
  let dropped = 0;
  for (const p of (j.products || [])) {
    const rate = num(p.interest_rate);
    const name = (p.product_name || '').toString().trim();
    if (!name || rate === null || rate < 1 || rate > 60) { dropped++; continue; }
    good.push({
      product_name: name,
      provider: (p.provider || j.source || '').toString().trim(),
      interest_rate: rate,
      min_monthly_income: num(p.min_monthly_income) ?? 0,
      min_credit_score: Math.min(900, Math.max(300, num(p.min_credit_score) ?? 300)),
      max_credit_score: num(p.max_credit_score),
      min_age: num(p.min_age), max_age: num(p.max_age),
      allowed_employment: emp(p.allowed_employment),
      eligibility_text: (p.eligibility_text || '').toString().slice(0, 500),
    });
  }
  return { json: { source: j.source, url: j.url, products: good, dropped, error: j.error || null } };
});
